<script lang="ts">
 import {api,message} from './workspace';
 export let description='';export let image='/api/shares/default-photo.jpg';export let title='Your invitation';export let disabled=false;
 export let uploading=false;let error='';
 async function upload(event:Event){const input=event.currentTarget as HTMLInputElement;const file=input.files?.[0];if(!file)return;
  error='';if(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>5*1024*1024){error='Choose a JPG, PNG, or WebP photo under 5 MB.';input.value='';return;}
  uploading=true;try{const form=new FormData();form.append('file',file);const result=await api.call<{url:string}>('upload',{},form);if(!result?.url)throw new Error('The photo could not be uploaded.');image=result.url;}catch(e){error=message(e);}finally{uploading=false;input.value='';}}
</script>
<div class="preview-fields"><label>Preview description<textarea bind:value={description} maxlength="300" rows="3" disabled={disabled||uploading} placeholder="What are you inviting people to explore? Give them a reason to open the link."></textarea><small>A sentence or two, 20–300 characters. This appears beside the photo when your link is shared.</small></label><label>Preview photo<input type="file" accept="image/jpeg,image/png,image/webp" on:change={upload} disabled={disabled||uploading}/></label><p class="fine">{uploading?'Uploading photo…':'Choose a landscape photo you’re comfortable making public, or keep the default.'}</p><button type="button" class="text-button" on:click={()=>image='/api/shares/default-photo.jpg'} disabled={disabled||uploading}>Use default photo</button>{#if error}<p class="alert" role="alert">{error}</p>{/if}<article class="share-card"><img src={image||'/api/shares/default-photo.jpg'} alt="Selected invitation or experiment cover"/><div><span class="eyebrow">REGENERATE SKAGIT</span><h3>{title}</h3><p>{description||'Add a description so people know what’s inside.'}</p></div></article></div>
